class Solution {
    /**
     * Given an integer n, return true if it is a power of three. Otherwise, return false.
     * An integer n is a power of three, if there exists an integer x such that n == 3^x.
     *
     * Example 1:
     * In: n = 27
     * Out: true
     * Explanation: 27 = 3^3
     *
     * Example 2:
     * In: n = 0
     * Out: false
     * Explanation: There is no x where 3^x = 0.
     *
     * Example 3:
     * In: n = -1
     * Out: false
     * Explanation: There is no x where 3x = (-1).
     *
     * Constraints:
     * -231 <= n <= 231 - 1
     *
     * Follow up: Could you solve it without loops/recursion?
     *
     * @param n The integer to check.
     * @return True if n is a power of three, false otherwise.
     */
    public boolean isPowerOfThree(int n) {
        if (n <= 0) {
            return false;
        }

        // A number is a power of three if and only if it is divisible by 3.
        // We can check this by repeatedly dividing by 3 until we get 1.
        // If at any point we get a non-integer result, then it's not a power of three.
        // Also, if the final result is 1, then it is a power of three.

        return (n > 0) && (n % 3 == 0) && (powerOfThreeHelper(n));
    }

    private boolean powerOfThreeHelper(int n) {
        if (n == 1) {
            return true;
        }
        if (n % 3 != 0) {
            return false;
        }
        return powerOfThreeHelper(n / 3);
    }
}
